	"github.com/aws/aws-sdk-go-v2/service/bedrockruntime"
	"github.com/aws/aws-sdk-go-v2/service/sts"
)

type BedrockConfig struct {
	Region  string `toml:"region"`
	ModelID string `toml:"model_id"`

	// Profile, when set, selects a named profile from the shared AWS config
	// and credentials files instead of the default chain. Handy for local
	// dev; leave empty in prod so IRSA / Pod Identity take over.
	Profile string `toml:"profile"`

	// RoleARN, when set, wraps the resolved base credentials with an
	// AssumeRole call. Use for cross-account setups where IRSA grants a
	// role in one account and Bedrock lives in another. Base credentials
	// (from IRSA, profile, env, etc.) must be allowed to sts:AssumeRole it.
	RoleARN         string `toml:"role_arn"`
	RoleSessionName string `toml:"role_session_name"`
	ExternalID      string `toml:"external_id"`
}

type Bedrock struct {
	cfg    BedrockConfig
	client *bedrockruntime.Client
}

func NewBedrock(cfg BedrockConfig) (*Bedrock, error) {
	if cfg.ModelID == "" {
		cfg.ModelID = "us.anthropic.claude-sonnet-4-6-v1:0"
	}

	opts := []func(*awsconfig.LoadOptions) error{awsconfig.WithRegion(cfg.Region)}
	if cfg.Profile != "" {
		opts = append(opts, awsconfig.WithSharedConfigProfile(cfg.Profile))
	}

	awsCfg, err := awsconfig.LoadDefaultConfig(context.Background(), opts...)
	if err != nil {
		return nil, fmt.Errorf("aws config: %w", err)
	}

	if cfg.RoleARN != "" {
		provider := stscreds.NewAssumeRoleProvider(sts.NewFromConfig(awsCfg), cfg.RoleARN, func(o *stscreds.AssumeRoleOptions) {
			if cfg.RoleSessionName != "" {
				o.RoleSessionName = cfg.RoleSessionName
			}
			if cfg.ExternalID != "" {
				o.ExternalID = aws.String(cfg.ExternalID)
			}
		})
		awsCfg.Credentials = aws.NewCredentialsCache(provider)
	}

	return &Bedrock{cfg: cfg, client: bedrockruntime.NewFromConfig(awsCfg)}, nil
}

