// mock-ai is a stub webhook that returns a canned assessment, so the
// scorer has something to chew on without burning real API keys.
//
// The reputation deductions are driven by the deterministic components
// (missing_custx_ticket, thin_description), so a fixed AI response is
// sufficient for testing the reputation + telemetry pipeline.
package main

import (
	"encoding/json"
	"log"
	"net/http"
)

func main() {
	http.HandleFunc("/score", func(w http.ResponseWriter, r *http.Request) {
		log.Printf("mock-ai: %s %s", r.Method, r.URL.Path)
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]any{
			"description_quality": 100,
			"privilege_concern":   0,
			"anomalies":           0,
			"reasoning":           "mock-ai: canned response for local testing",
		})
	})
	log.Println("mock-ai listening on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}

