package ai

import (
	"context"
	"fmt"
	"log/slog"
	"math/rand/v2"
	"sync"
	"time"
)

// RandomConfig configures the Random provider. This provider is for local
// development and integration testing only — it does not call any model
// and returns randomized values within the valid Assessment ranges.
type RandomConfig struct {
	// Seed, when non-zero, makes output deterministic across runs. Zero
	// seeds with time.Now().UnixNano() for each process.
	Seed int64 `toml:"seed"`
}

// Random is a test-only Provider. Do not ship to production.
type Random struct {
	mu  sync.Mutex
	rng *rand.Rand
}

func NewRandom(cfg RandomConfig) *Random {
	slog.Warn("ai provider is 'random' — assessments are fabricated, for testing only")
	seed := cfg.Seed
	if seed == 0 {
