package televibe

import (
	"sync"
	"sync/atomic"
	"testing"
)

func TestReserveOrSkip_ExactlyOneWinner(t *testing.T) {
	a := &App{pending: map[string]string{}}

	const goroutines = 100
	var start sync.WaitGroup
	var done sync.WaitGroup
	var winners atomic.Int32

	start.Add(1)
	done.Add(goroutines)
	for i := 0; i < goroutines; i++ {
		go func() {
			defer done.Done()
			start.Wait()
			if a.reserveOrSkip("req-1") {
				winners.Add(1)
			}
		}()
	}
	start.Done()
	done.Wait()

	if got := winners.Load(); got != 1 {
		t.Errorf("exactly one goroutine should reserve, got %d winners", got)
	}
	if _, ok := a.pending["req-1"]; !ok {
		t.Errorf("winning goroutine should have left a reservation in place")
	}
}

func TestReserveOrSkip_AfterReleaseReacquires(t *testing.T) {
	a := &App{pending: map[string]string{}}
	if !a.reserveOrSkip("req-1") {
		t.Fatal("first reservation should succeed")
	}
	if a.reserveOrSkip("req-1") {
		t.Fatal("second reservation should fail while held")
	}
	a.releasePending("req-1")
	if !a.reserveOrSkip("req-1") {
		t.Fatal("reservation after release should succeed (covers retry-after-failure path)")
	}
}

func TestReserveOrSkip_TicketedIDIsNotReacquired(t *testing.T) {
	a := &App{pending: map[string]string{}}
	if !a.reserveOrSkip("req-1") {
		t.Fatal("reservation should succeed")
	}
	a.recordTicket("req-1", "ITSM-42")
	if a.reserveOrSkip("req-1") {
		t.Fatal("request already holding a ticket must not be reserved again")
	}
	if got := a.pending["req-1"]; got != "ITSM-42" {
		t.Errorf("recordTicket should leave the real key in place, got %q", got)
	}
}

