package jira

import (
	"strings"
	"testing"
)

// This is the regression test for the rehydration bug: the regex has to
// match request IDs inside the exact wiki markup buildDescription emits,
// including the "*" that closes the Jira bold on "*Teleport Request ID:*".
func TestReqIDRE_ExtractsFromBuildDescription(t *testing.T) {
	cases := []struct {
		name string
		in   TicketInput
		want string
	}{
		{
			name: "uuid-style id, plain ticket",
			in:   TicketInput{RequestID: "abc12345-1234-1234-1234-abcdef012345", Tier: "low"},
			want: "abc12345-1234-1234-1234-abcdef012345",
		},
		{
			name: "uuid-style id, escalation ticket",
			in:   TicketInput{RequestID: "abc12345-1234-1234-1234-abcdef012345", Tier: "high", Escalation: true},
			want: "abc12345-1234-1234-1234-abcdef012345",
		},
		{
			name: "short alphanumeric id",
			in:   TicketInput{RequestID: "req-987", Tier: "medium"},
			want: "req-987",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			desc := buildDescription(tc.in)
			m := reqIDRE.FindStringSubmatch(desc)
			if len(m) < 2 {
				t.Fatalf("regex did not match. description was:\n%s", desc)
			}
			if m[1] != tc.want {
				t.Errorf("captured %q, want %q", m[1], tc.want)
			}
		})
	}
}

// Defensive: ensure unstyled formatting still matches, so manual edits to
// the template (removing bold, adding whitespace) don't silently break
// rehydration again.
func TestReqIDRE_ExtractsFromAlternativeFormats(t *testing.T) {
	cases := map[string]string{
		"plain colon-space":    "Teleport Request ID: abc-123",
		"no space after colon": "Teleport Request ID:abc-123",
		"bold wiki markup":     "* *Teleport Request ID:* abc-123",
		"extra surrounding":    "blah\n* *Teleport Request ID:* abc-123 more text\nfoo",
	}
	for name, in := range cases {
		t.Run(name, func(t *testing.T) {
			m := reqIDRE.FindStringSubmatch(in)
			if len(m) < 2 || m[1] != "abc-123" {
				t.Errorf("got %v, want capture of %q in input %q", m, "abc-123", in)
			}
		})
	}
}

func TestReqIDRE_NoMatchWhenMarkerAbsent(t *testing.T) {
	cases := []string{
		"",
		"just some random text",
		"Teleport Access Request:\nabc-123", // similar but different label
	}
	for _, in := range cases {
		if m := reqIDRE.FindStringSubmatch(in); m != nil {
			t.Errorf("unexpected match on %q: %v", in, m)
		}
	}
}

// Sanity check that the emitted description still contains the exact
// marker string the regex anchors on, so drift in buildDescription trips
// this test before the field deployment.
func TestBuildDescription_ContainsMarker(t *testing.T) {
	desc := buildDescription(TicketInput{RequestID: "abc-123"})
	if !strings.Contains(desc, "Teleport Request ID:") {
		t.Errorf("buildDescription output missing the 'Teleport Request ID:' marker")
	}
}

