// Regression for the persist race: two in-flight persist calls could
// each snapshot independently and the slower os.Rename would land last,
// silently overwriting the newer state. This test fires N concurrent
// Assess calls for distinct users and asserts all N updates land on
// disk. Under the buggy implementation this fails intermittently
// because the final file is missing some users.
func TestAssess_ConcurrentPersistsDoNotDropUpdates(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "reputation.json")
	s, err := NewStore(baseCfg(path))
	if err != nil {
		t.Fatalf("NewStore: %v", err)
	}

	const N = 64
	var wg sync.WaitGroup
	wg.Add(N)
	for i := 0; i < N; i++ {
		go func(i int) {
			defer wg.Done()
			user := fmt.Sprintf("user-%d", i)
			if _, err := s.Assess(context.Background(), user, map[string]int{
				"missing_custx_ticket": 1,
			}); err != nil {
				t.Errorf("Assess(%s): %v", user, err)
			}
		}(i)
	}
	wg.Wait()

	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read persist file: %v", err)
	}
	var rep map[string]int
	if err := json.Unmarshal(data, &rep); err != nil {
		t.Fatalf("parse persisted state: %v", err)
	}
	if got := len(rep); got != N {
		t.Fatalf("disk state has %d users, want %d — concurrent persists dropped writes", got, N)
	}
	for i := 0; i < N; i++ {
		user := fmt.Sprintf("user-%d", i)
		if _, ok := rep[user]; !ok {
			t.Errorf("user %s missing from persisted state", user)
		}
	}
}

